f1_observability.serialized_dashboard:
{
  "datasets": [
    {
      "name": "eval_history",
      "displayName": "RAG eval score history",
      "queryLines": [
        "SELECT metric, score, timestamp\n",
        "FROM agent_factory_dev.${resources.schemas.agent_factory.name}.eval_results\n",
        "WHERE domain = 'f1' AND target = 'dev'\n",
        "  AND metric LIKE 'rag_eval.%'\n",
        "ORDER BY timestamp\n"
      ]
    },
    {
      "name": "latest_scores",
      "displayName": "Latest RAG eval scores",
      "queryLines": [
        "SELECT metric, score, timestamp\n",
        "FROM (\n",
        "  SELECT metric, score, timestamp,\n",
        "         ROW_NUMBER() OVER (PARTITION BY metric ORDER BY timestamp DESC) AS rn\n",
        "  FROM agent_factory_dev.${resources.schemas.agent_factory.name}.eval_results\n",
        "  WHERE domain = 'f1' AND target = 'dev'\n",
        "    AND metric LIKE 'rag_eval.%'\n",
        ")\n",
        "WHERE rn = 1\n",
        "ORDER BY metric\n"
      ]
    },
    {
      "name": "endpoint_traffic",
      "displayName": "Serving endpoint traffic",
      "queryLines": [
        "SELECT DATE(u.request_time) AS request_date, COUNT(*) AS request_count\n",
        "FROM system.serving.endpoint_usage u\n",
        "JOIN system.serving.served_entities e ON u.served_entity_id = e.served_entity_id\n",
        "WHERE e.endpoint_name = 'f1-agent-dev'\n",
        "GROUP BY DATE(u.request_time)\n",
        "ORDER BY request_date\n"
      ]
    }
  ],
  "pages": [
    {
      "name": "observability",
      "displayName": "Observability",
      "pageType": "PAGE_TYPE_CANVAS",
      "layout": [
        {
          "widget": {
            "name": "eval_history_chart",
            "queries": [
              {
                "name": "main_query",
                "query": {
                  "datasetName": "eval_history",
                  "fields": [
                    {
                      "name": "timestamp",
                      "expression": "`timestamp`"
                    },
                    {
                      "name": "score",
                      "expression": "`score`"
                    },
                    {
                      "name": "metric",
                      "expression": "`metric`"
                    }
                  ],
                  "disaggregated": true
                }
              }
            ],
            "spec": {
              "version": 3,
              "widgetType": "line",
              "encodings": {
                "x": {
                  "fieldName": "timestamp",
                  "displayName": "Timestamp",
                  "scale": {
                    "type": "temporal"
                  }
                },
                "y": {
                  "fieldName": "score",
                  "displayName": "Score",
                  "scale": {
                    "type": "quantitative"
                  }
                },
                "color": {
                  "fieldName": "metric",
                  "displayName": "Metric",
                  "scale": {
                    "type": "categorical"
                  }
                }
              }
            }
          },
          "position": {
            "x": 0,
            "y": 0,
            "width": 6,
            "height": 6
          }
        },
        {
          "widget": {
            "name": "latest_scores_table",
            "queries": [
              {
                "name": "main_query",
                "query": {
                  "datasetName": "latest_scores",
                  "fields": [
                    {
                      "name": "metric",
                      "expression": "`metric`"
                    },
                    {
                      "name": "score",
                      "expression": "`score`"
                    },
                    {
                      "name": "timestamp",
                      "expression": "`timestamp`"
                    }
                  ],
                  "disaggregated": true
                }
              }
            ],
            "spec": {
              "version": 3,
              "widgetType": "table",
              "encodings": {
                "columns": [
                  {
                    "fieldName": "metric",
                    "displayName": "Metric"
                  },
                  {
                    "fieldName": "score",
                    "displayName": "Score"
                  },
                  {
                    "fieldName": "timestamp",
                    "displayName": "Last run"
                  }
                ]
              }
            }
          },
          "position": {
            "x": 0,
            "y": 6,
            "width": 6,
            "height": 6
          }
        },
        {
          "widget": {
            "name": "endpoint_traffic_chart",
            "queries": [
              {
                "name": "main_query",
                "query": {
                  "datasetName": "endpoint_traffic",
                  "fields": [
                    {
                      "name": "request_date",
                      "expression": "`request_date`"
                    },
                    {
                      "name": "request_count",
                      "expression": "`request_count`"
                    }
                  ],
                  "disaggregated": true
                }
              }
            ],
            "spec": {
              "version": 3,
              "widgetType": "bar",
              "encodings": {
                "x": {
                  "fieldName": "request_date",
                  "displayName": "Date",
                  "scale": {
                    "type": "temporal"
                  }
                },
                "y": {
                  "fieldName": "request_count",
                  "displayName": "Requests",
                  "scale": {
                    "type": "quantitative"
                  }
                }
              }
            }
          },
          "position": {
            "x": 0,
            "y": 12,
            "width": 6,
            "height": 6
          }
        }
      ]
    }
  ]
}

f1_genie.serialized_space:
{
  "version": 2,
  "config": {
    "sample_questions": [
      {
        "id": "2e2d80f87c285ed2b8bd9a6c2d2349c2",
        "question": [
          "Who scored the most points in 2025?"
        ]
      },
      {
        "id": "973ff7607a38c1f68e558afc6a1bb3c2",
        "question": [
          "Which constructor had the fastest average pit stop in 2024?"
        ]
      },
      {
        "id": "6777ebd6a9cc3bf3bcbf1c87018808fe",
        "question": [
          "How many races did each driver retire from in 2023?"
        ]
      }
    ]
  },
  "data_sources": {
    "tables": [
      {
        "identifier": "agent_factory_dev.${resources.schemas.f1.name}.constructors"
      },
      {
        "identifier": "agent_factory_dev.${resources.schemas.f1.name}.drivers"
      },
      {
        "identifier": "agent_factory_dev.${resources.schemas.f1.name}.pit_stops"
      },
      {
        "identifier": "agent_factory_dev.${resources.schemas.f1.name}.races"
      },
      {
        "identifier": "agent_factory_dev.${resources.schemas.f1.name}.results"
      }
    ]
  },
  "instructions": {
    "text_instructions": [
      {
        "id": "0053d02c96642798b9919e6f314a21b5",
        "content": [
          "Points are awarded 25-18-15-12-10-8-6-4-2-1 for positions 1 to 10.\nA podium is a finish in position 1, 2 or 3.\nIn the results table, status \"Finished\", the exact status \"Lapped\", or\na lapped count such as \"+1 Lap\" all mean the driver was classified at\nthe end of the race, just not on the lead lap. Any other status (for\nexample \"Collision\", \"Engine\", \"Accident\") means the driver did not\nfinish (DNF); the status text is the reason. Do not treat \"Lapped\" as\na DNF: it is a distinct status from the \"+N Lap(s)\" family and easy to\nmiss if you only filter on the \"+\" prefix.\npit_stops.duration_seconds is time in the pit lane, not just time\nstationary. It can include long outliers (tens of minutes) from red\nflags or race stoppages while a car sits in the pits: for \"average\" or\n\"fastest\" pit stop questions, use the median, or filter to stops under\n60 seconds, rather than a plain mean, unless the question explicitly\nasks about stoppage-affected stops."
        ]
      }
    ]
  }
}
